 "OpenAlex 오늘 한도를 다 써서 참고문헌을 읽지 못했습니다. 설정에서 OpenAlex 키를 넣거나 내일 다시 찾으세요.": "Today's OpenAlex allowance is spent, so the references could not be read. Add an OpenAlex key in settings or search again tomorrow.",
 "OpenAlex 요청 {0}회로 각 논문에 적힌 이 저자의 소속을 읽고, 보유 논문·ORCID 경력과 맞춰 가립니다": "Reads this author's affiliation on each paper ({0} OpenAlex requests) and checks it against your library and the author's ORCID record",
 "OpenAlex 원본 열기": "Open the OpenAlex source",
 "OpenAlex 원본에서 저널 확인": "Check the journals at OpenAlex",
 "OpenAlex 저널 수": "OpenAlex journals",
 "OpenAlex 주제로 탐색": "Browse by OpenAlex subject",
 "OpenAlex 키·AI·번역 연결은 Zotero 설정 → Style Custom 맨 위 ‘먼저 할 것’에서 확인합니다.": "The OpenAlex key, AI and translation connections are checked at the top of Zotero Settings → Style Custom, under 'Start here'.",
 "OpenAlex 키가 없어 자동 조회를 쉬고 있습니다. 설정 → 인용 수·IF에 키를 넣거나, 우클릭 → 선택한 문헌 인용 수 새로고침을 실행하세요.": "Without an OpenAlex key the automatic lookup is paused. Enter a key under Settings → Citations · IF, or right-click → Refresh citations for selected items.",
 "OpenAlex 프로필에만 있는 소속입니다. 합쳐진 동명이인의 소속일 수 있습니다": "This affiliation is only on the OpenAlex profile. It may belong to a namesake merged into it",
 "OpenAlex 하루 한도를 다 썼습니다. {0}묶음이 남았고, 한국 시간 오전 9시에 초기화됩니다. 지금까지 확인한 결과는 저장했습니다.": "The OpenAlex daily allowance is used up. {0} batches are left and it resets at midnight UTC. What has been checked so far is saved.",
 "OpenAlex 하루 한도를 다 썼습니다. {0}종이 남았고, 한국 시간 오전 9시에 초기화됩니다.\n지금까지 받은 값은 저장했으니 내일 다시 실행하면 남은 것부터 이어서 채웁니다.": "The OpenAlex daily allowance is used up. {0} are left and it resets at midnight UTC.\nWhat has arrived is saved, so running it again tomorrow carries on from where it stopped.",
 "OpenAlex 하루 한도를 다 썼습니다. 한국 시간 오전 9시에 초기화되고, 다시 실행하면 남은 것부터 이어서 채웁니다.": "The OpenAlex daily allowance is used up. It resets at midnight UTC; run it again after that and it carries on from where it stopped.",
 "OpenAlex 하루 한도를 다 썼습니다. 한국 시간 오전 9시에 초기화되니 그때 다시 확인하세요.": "The day's OpenAlex budget is spent. It resets at 09:00 Korean time; check again then.",
 "OpenAlex 확인 {0}": "OpenAlex checked {0}",
 "OpenAlex가 찾은 논문이 선택한 문헌과 제목이 다릅니다. 문헌에 DOI를 채운 뒤 다시 찾으세요.": "The paper OpenAlex found has a different title from the selected item. Add a DOI to the item and search again.",
 "OpenAlex에 이 논문의 참고문헌 목록이 없어 순서를 짤 수 없습니다.": "OpenAlex has no reference list for this paper, so no order can be made.",
 "OpenAlex에 이 논문의 참고문헌 목록이 없어 인용한 논문 {0}편만 살폈습니다{1}": "OpenAlex has no reference list for this paper, so only {0} citing papers were examined{1}",
 "OpenAlex에 이 저널의 2년 평균 피인용이 없습니다. 0이 아니라 알 수 없는 값입니다.": "OpenAlex has no 2-year mean citedness for this journal. The value is unknown, not zero.",
