 "[그림 주석]": "[image annotation]",
 "[필기 주석]": "[ink annotation]",
 "api.openalex.org에만 보냅니다. openalex.org 계정에서 무료로 받습니다. 비워 두고 ZotPoP에 넣은 키가 있으면 그 키를 씁니다. 둘 다 없으면 목록의 자동 인용 수 조회가 멈추고, 우클릭 → 선택한 문헌 인용 수 새로고침과 논문 추가·수정 때의 조회만 하루 약 10건 됩니다.": "Sent only to api.openalex.org. Get one free from your openalex.org account. Left blank, the key entered in ZotPoP is used if there is one. With neither, the list's automatic citation lookups stop; right-click → Refresh citation counts for selected items and the lookup when a paper is added or edited still work, at about 10 a day.",
 "doi.org에서 열기": "Open on doi.org",
