 "게재됨": "Published",
 "게재됨 →": "Published →",
 "게재본 가져와 연결": "Import published version and link",
 "게재본 연결 안 됨 {0}편": "{0} published versions not linked",
 "게재본: {0}": "Published: {0}",
 "게재본으로 옮기기": "Move to the published version",
 "게재본으로 찾은 항목도 프리프린트입니다. 실제 게재본을 라이브러리에 추가한 뒤 합치세요.": "The item found as the published version is also a preprint. Add the real published version to your library, then merge.",
 "게재본을 가져오는 중…": "Importing the published version…",
 "게재본을 가져오지 못했습니다. 잠시 뒤 다시 시도하세요.": "The published version could not be imported. Try again in a moment.",
 "게재본을 가져와 이 프리프린트와 연결하고 태그·읽기 상태·메모를 옮깁니다 (프리프린트는 그대로 둡니다)": "Imports the published version, links it to this preprint and carries over tags, reading status and memo (the preprint is left as it is)",
 "게재본을 가져와 프리프린트와 연결했습니다 — {0}": "Imported the published version and linked it to the preprint — {0}",
 "게재본을 연결하는 중…": "Linking the published version…",
 "게재본이 다른 라이브러리에 있어 연결하지 못했습니다. 같은 라이브러리로 옮긴 뒤 다시 시도하세요.": "The published version is in a different library, so it could not be linked. Move it into the same library and try again.",
 "게재본이 다른 라이브러리에 있어 합치지 못했습니다. 같은 라이브러리로 옮긴 뒤 다시 시도하세요.": "The published version is in another library. Move it to the same library and try again.",
 "게재본이 이 라이브러리에 없어 합칠 수 없습니다. 게재본을 먼저 라이브러리에 추가하세요.": "The published version is not in this library, so they cannot be merged. Add it to the library first.",
 "격식체 쪽": "More formal",
 "결과": "Result",
 "결과 복사": "Copy result",
 "계정이 아닙니다. Crossref는 요청 URL에 ?mailto=주소를 붙이면 익명 요청보다 빠른 대기열(polite pool)에 넣어 줍니다. OpenAlex에도 같은 주소가 붙지만 지금은 속도 이점이 없습니다. 입력한 주소는 이 두 서비스의 서버 기록에 요청마다 남습니다. 비워 두면 ZotPoP의 연락처 이메일이 있으면 그것을 쓰고, 둘 다 없으면 보내지 않습니다(조회는 그대로 동작하되 익명 대기열을 씁니다). Zotero 로그인 계정을 대신 쓰는 일은 없습니다.": "This is not an account. Crossref puts a request carrying ?mailto=your-address into a faster queue than an anonymous one — its polite pool. OpenAlex also receives the address, but it gives no speed benefit now. In exchange, the address you enter appears in those two services' server logs on every request. Leave it blank and ZotPoP's contact e-mail is used if it has one; with neither, nothing is sent: lookups still work, they just use the anonymous queue. Your Zotero sign-in is never used instead.",
 "고를 수 있는 항목이 없습니다.": "Nothing to choose.",
 "공개 접근 ({0})": "Open access ({0})",
 "공개 접근본이 없습니다.": "No open-access copy.",
 "공동 저자로 실린 문헌은 관련된 관심 저자 모두에게 집계됩니다": "A paper with more than one followed author counts for each of them",
 "공식 IF를 아직 확인하지 못했습니다.": "The official IF has not been checked yet.",
 "공식 JCR 카테고리 보기": "Official JCR categories",
 "공식 JCR 카테고리 자료를 불러오지 못했습니다.": "The official JCR category data could not be loaded.",
 "공식 JIF 미확인. OpenAlex 값은 ‘OA 2년 평균 피인용’ 열에서 확인할 수 있습니다.": "No official JIF found. The OpenAlex figure is in the ‘OA 2-yr mean citedness’ column.",
 "공식 JIF가 아니라 OpenAlex 2년 평균 피인용 추정치입니다.": "An OpenAlex two-year mean citedness estimate, not an official JIF.",
 "공식 JIF가 아니라 추정치입니다.": "This is an estimate, not the official JIF.",
 "공식 JIF가 있는 저널은 그대로 두고, 없는 저널만 ~추정치로 채웁니다.": "Journals with an official JIF are left alone; only the rest are filled with a ~estimate.",
