 "그림으로 저장": "Save as image",
 "근거 칸 추가": "Add evidence fields",
 "글꼴 크기": "Font size",
 "글꼴 크기 줄이기": "Smaller text",
 "글꼴 크기 키우기": "Larger text",
 "글자와 배경의 대비가 4.5:1 이상이어야 읽을 수 있습니다. 더 어둡거나 밝은 색을 고르세요.": "Text and background need a contrast of at least 4.5:1 to be read. Choose a darker or lighter colour.",
 "글자와 배경의 대비가 {0}:1이라 이 조합은 PDF에 칠하지 않습니다. 4.5:1 이상이 되게 고르세요.": "Text and background contrast is {0}:1, so this pair is not painted on the PDF. Choose colours that reach 4.5:1.",
