 "기능별 작업 패널과 표시 밀도·목록 크기를 조절합니다.": "Controls the panels for each feature, the density and the list size.",
 "기록 간격·무활동 제외·상태 연동을 조절합니다. 읽기 기록은 로컬 파일에 저장합니다.": "Controls the recording interval, the idle cut-off and the link to reading status. The history is kept in a local file.",
 "기록·표시 갱신 간격 (ms)": "Record and refresh interval (ms)",
 "기록된 읽기 시간으로 상태를 정합니다. 30초 넘게 읽은 문헌은 ‘읽는 중’으로 보입니다(‘읽기를 시작하면 읽는 중으로 자동 표시’도 켜져 있어야 함). 목록의 상태 열은 ‘읽기 상태 열 표시’가 정합니다.": "Lets recorded reading time decide the status: a paper read for more than 30 seconds shows as Reading (with 'Automatically mark as \"reading\" when reading starts' also on). The status column in the list is set by 'Show the Status column'.",
 "기록이 없어도 0초 표시": "Show 0s even with no record",
 "기본": "Default",
 "기본 1초. 비활성 창과 무활동 시간은 제외합니다.": "One second by default. Inactive windows and idle time are excluded.",
 "기본 Custom 열 표시": "Show the default custom columns",
