 "리더 사이드바 표시": "Show reader sidebar",
 "리더 사이드바와 세로 탭·저장 그룹을 조절합니다.": "Controls the reader sidebar, vertical tabs and saved groups.",
 "리더 패널의 ‘번역’에서 문단별 번역에만 씁니다. deepl.com에서 무료 키(:fx로 끝남, 한 달 50만 자)를 받을 수 있고, 키 끝으로 무료/유료 서버를 알아서 고릅니다. 키는 DeepL 서버의 인증 헤더에만 보내며 번역 버튼을 눌렀을 때(번역 전에 이번 달 남은 양을 묻는 요청 포함)만 사용합니다. 번역기는 DeepL → Translate for Zotero(설치되어 있으면) → AI 순서로 고르며, 한 번역기가 멈추면 패널에서 다음 번역기로 그 실행이 맡았던 문단 중 남은 것만 이어서 번역할 수 있습니다.": "Used only for the paragraph translation in the reader panel's Translation tab. A free key (ending in :fx, 500,000 characters a month) is available from deepl.com, and the free or paid server is chosen from the end of the key. The key goes only to DeepL in its authorization header, and only when you press a translate button (including the request for this month's remaining allowance made before translating). Translators are tried in the order DeepL → Translate for Zotero (if installed) → AI; when one stops, the panel can carry on with the next one for the paragraphs of that run still left.",
