 "비교 다음 페이지": "Next comparison page",
 "비교 이전 페이지": "Previous comparison page",
 "비교 중 {0}편": "Comparing {0} papers",
 "비교 중인 문헌의 근거 칸과, 주석 탭에서 고른 주석을 한 노트로 모읍니다. 각 문헌과 주석 페이지로 가는 링크가 들어갑니다": "Gathers the evidence fields of the compared papers and the annotations picked in the Annotations tab into one note, with links to each paper and annotation page",
