 "숫자를 입력하세요.": "Enter a number.",
 "쉼표나 줄바꿈으로 나눠 적습니다 (예: Notch, sonic hedgehog). 문단 번역에서 이 용어는 그대로 둡니다. TP53·IL-6 같은 유전자·단백질 이름, Escherichia coli·E. coli 같은 종 이름, 5 µM·10 mg/mL 같은 단위는 적지 않아도 그대로 둡니다. DeepL과 Translate for Zotero에 적용되며, AI 번역은 지시문으로 같은 규칙을 따릅니다.": "Separate with commas or new lines (for example: Notch, sonic hedgehog). Paragraph translation leaves these terms as written. Gene and protein names such as TP53 and IL-6, species such as Escherichia coli and E. coli, and units such as 5 µM and 10 mg/mL are kept without being listed. Applies to DeepL and Translate for Zotero; AI translation follows the same rule through its prompt.",
