 "이 범위에 문헌이 없습니다. 범위를 라이브러리로 바꾸세요.": "No papers in this scope. Switch the scope to the library.",
 "이 범위에는 OpenAlex에서 확인한 문헌이 없어 새 논문을 찾을 수 없습니다. 관계 그래프 탭에서 인용 목록을 먼저 가져오세요.": "No paper in this scope has been looked up on OpenAlex, so there is nothing to search from. Fetch the reference lists on the graph tab first.",
 "이 범위에는 최근 활동 시각이 기록된 문헌이 없습니다. 문헌을 열어 읽거나 추가·수정하면 여기에 표시됩니다.": "Nothing in this scope has a recorded activity time yet. Items appear here once opened, added or edited.",
 "이 범위에서 연결이 없는 논문": "Unconnected in this scope",
 "이 범위에서 연결이 없는 논문 {0}": "Papers with no connection in this scope {0}",
 "이 범위에서는 서로 인용하거나 참고문헌을 공유하는 논문이 없습니다. 범위를 넓혀보세요.": "In this scope no papers cite one another or share references. Try widening it.",
 "이 범위의 노트": "Notes in scope",
 "이 범위의 노트 {0}개": "{0} notes in this scope",
 "이 범위의 논문은 OpenAlex에 참고문헌 목록이 없습니다. 관련 문헌 연결을 대신 보여줍니다.": "OpenAlex has no reference lists for the papers in this range. Related-item links are shown instead.",
 "이 범위의 문헌 {0}편을 인용한 최근 {1}일 논문을 OpenAlex에서 찾습니다. 내 문헌을 많이 인용한 순서로 보여 줍니다.": "Asks OpenAlex for papers from the last {1} days that cite the {0} papers here, the ones citing most of yours first.",
 "이 범위의 문헌을 인용한 새 논문입니다. 내 문헌을 많이 인용한 순서입니다.": "New papers that cite this scope, the ones citing most of your own first.",
 "이 범위의 첨부파일": "Attachments in this range",
