 "AI 요약·대화·제목 번역·함께 읽기 결과를 쓸 언어입니다. 기본값은 패널 언어를 따르며, 전문 용어는 논문에 쓰인 영어 그대로 둡니다. 리더 패널의 문단 번역 언어는 ‘논문 번역 언어’가 따로 정합니다.": "设置 AI 摘要、问答、题名翻译和多篇对比的输出语言。默认跟随面板语言，专业术语保留论文中的英文写法。阅读面板的段落翻译由“论文翻译目标语言”单独控制。",
