 "AI는 이 Mac의 AI 브리지를 자동으로 찾아 쓰고, 다른 서버·모델·번역기와 요청 문구는 여기서 정합니다. 요청은 버튼을 누를 때만 보냅니다. ‘논문을 열면 AI 요약을 자동으로 만들기’를 켜면 논문을 열 때도 보냅니다.": "可使用已配置的本地 AI 桥接服务，或在此填写其他服务地址、模型和提示词。通常只在点击相应按钮时发送请求；若启用“打开论文自动生成 AI 摘要”，打开论文时也会发送请求。",
