 "api.openalex.org에만 보냅니다. openalex.org 계정에서 무료로 받습니다. 비워 두고 ZotPoP에 넣은 키가 있으면 그 키를 씁니다. 둘 다 없으면 목록의 자동 인용 수 조회가 멈추고, 우클릭 → 선택한 문헌 인용 수 새로고침과 논문 추가·수정 때의 조회만 하루 약 10건 됩니다.": "密钥仅发送至 api.openalex.org，可从自己的 OpenAlex 账户获取。此处留空时，会复用 ZotPoP 中的密钥；两处都未配置时，将停止列表中的自动引用查询。右键刷新所选条目的被引次数，以及添加或编辑条目时的查询仍可使用，每天约 10 次。",
