 "계정이 아닙니다. Crossref는 요청 URL에 ?mailto=주소를 붙이면 익명 요청보다 빠른 대기열(polite pool)에 넣어 줍니다. OpenAlex에도 같은 주소가 붙지만 지금은 속도 이점이 없습니다. 입력한 주소는 이 두 서비스의 서버 기록에 요청마다 남습니다. 비워 두면 ZotPoP의 연락처 이메일이 있으면 그것을 쓰고, 둘 다 없으면 보내지 않습니다(조회는 그대로 동작하되 익명 대기열을 씁니다). Zotero 로그인 계정을 대신 쓰는 일은 없습니다.": "此处填写 API 联系邮箱，并非登录账号。Crossref 会将带有 ?mailto=邮箱 参数的请求放入优先处理队列（polite pool）；OpenAlex 也会收到该邮箱，但目前不会因此加速。邮箱会出现在相应服务的请求日志中。此处留空时会复用 ZotPoP 的联系邮箱；两处都留空则不附带邮箱，查询仍可匿名进行。不会使用 Zotero 登录信息代替。",
