 "관심 저자에서 빼기": "取消关注",
 "관심 저자의 사진을 Wikidata(ORCID로, Wikimedia Commons의 사진), Google Scholar, ORCID에 적힌 개인 홈페이지 순서로 찾습니다. 저자를 열 때, ‘사진 찾기’를 누를 때, 새 논문 확인이 끝난 뒤 아직 찾지 않은 사람만 찾습니다. 찾은 것과 못 찾은 것은 두 달 동안 다시 묻지 않습니다.": "先通过 ORCID 在 Wikidata 匹配作者并查找 Wikimedia Commons 照片，再尝试 Google Scholar 和 ORCID 中列出的个人主页。打开作者详情、点击“查找照片”，或检查新论文时遇到尚未查询照片的作者，会发起查询。无论是否找到照片，结果都会缓存两个月，期间不重复查询。",
 "관심 저자의 사진을 찾는 중… Wikidata, Google Scholar, 각자의 홈페이지를 확인합니다.": "正在查找关注作者的照片，依次检查 Wikidata、Google Scholar 及作者主页…",
 "관심 저자의 특허 출원·등록을 찾는 데만 씁니다. data.uspto.gov에서 MyUSPTO 계정으로 무료 발급됩니다. 키는 api.uspto.gov에만 보내며, 비워 두면 특허 확인은 건너뜁니다.": "仅用于查询关注作者涉及的专利申请和授权记录。可使用 MyUSPTO 账户在 data.uspto.gov 免费获取密钥。密钥仅发送至 api.uspto.gov；留空时跳过专利查询。",
