 "기본값은 영어입니다. 영어·간체 중국어·한국어 또는 Zotero 언어 따르기를 선택하세요. 설정창과 패널은 바로 바뀝니다.": "默认使用英文。可选择英文、简体中文、韩语或跟随 Zotero。设置页和面板会立即切换语言。",
