 "리더 사이드바와 세로 탭·저장 그룹을 조절합니다.": "设置阅读侧栏、垂直标签页和已保存的标签页分组。",
 "리더 패널의 ‘번역’에서 문단별 번역에만 씁니다. deepl.com에서 무료 키(:fx로 끝남, 한 달 50만 자)를 받을 수 있고, 키 끝으로 무료/유료 서버를 알아서 고릅니다. 키는 DeepL 서버의 인증 헤더에만 보내며 번역 버튼을 눌렀을 때(번역 전에 이번 달 남은 양을 묻는 요청 포함)만 사용합니다. 번역기는 DeepL → Translate for Zotero(설치되어 있으면) → AI 순서로 고르며, 한 번역기가 멈추면 패널에서 다음 번역기로 그 실행이 맡았던 문단 중 남은 것만 이어서 번역할 수 있습니다.": "仅用于阅读面板“翻译”页中的段落翻译。可在 deepl.com 获取免费密钥，以 :fx 结尾，每月额度为 50 万字符；插件据密钥类型选择免费或付费服务地址。密钥仅通过认证请求头发送给 DeepL，且仅在点击翻译按钮后使用，包括翻译前查询剩余额度。服务依次尝试 DeepL、Translate for Zotero（如已安装）和 AI；某个服务停止后，可以换用下一个服务继续翻译本次任务中尚未完成的段落。",
