 "비어 있음": "空",
 "비우면 아래 기능이 꺼져 있습니다.": "将这些留空，下面的功能将保持关闭状态。",
 "비워 두면 기본 개요(핵심 주장 · 논리 흐름 · 근거의 강점·한계 · 공통 기반 · 논쟁 여지와 판가름할 증거 · 열린 질문)를 씁니다. 출력 언어와 '지어내지 말 것'은 항상 덧붙습니다.": "留空时使用默认提纲：核心结论、论证过程、证据的强度与局限、共同认识、争议点及决定性证据、尚待解决的问题。无论是否自定义，都会附加输出语言和“不得编造”的要求。",
 "비워 두면 논문 언어에 맞는 시스템 음성을 자동으로 고릅니다. 리더 패널의 ‘목소리’ 메뉴에서 고르면 여기에 저장됩니다. 음성은 내 컴퓨터에 설치된 것만 쓰며 인터넷으로 보내지 않습니다.": "留空时，自动选择与论文语言匹配的系统声音。在阅读面板的声音菜单中作出的选择会保存到此处。仅使用本机已安装的声音，不会为此将文本发送到互联网。",
 "비워 두면 이 Mac의 AI 브리지를 찾아 씁니다. 브리지는 이 Mac에 로그인된 Claude 계정으로 답하고, Claude가 한도에 걸리거나 답하지 못하면 ChatGPT 계정으로 답합니다(API 키 없음, 각 계정의 사용 한도 적용). 설치·제거는 플러그인 폴더의 bridge/install.sh, bridge/install.sh --uninstall. 다른 서버를 쓰려면 Chat Completions 형식 주소를 넣으세요. 이 주소가 항상 우선합니다. 예: https://api.openai.com/v1/chat/completions, 로컬 Ollama는 http://localhost:11434/v1/chat/completions": "留空时会尝试使用已配置的本地 AI 桥接服务。桥接默认使用本机登录的 Claude 账户；Claude 达到限额或未能响应时，改用 ChatGPT 账户，不使用 API 密钥，受各账户用量限制。配套安装脚本为插件目录中的 bridge/install.sh，卸载参数为 --uninstall。若填写其他兼容 Chat Completions 的完整服务地址，将优先使用该地址，例如 https://api.openai.com/v1/chat/completions；本地 Ollama 可使用 http://localhost:11434/v1/chat/completions。",
