 "쉼표나 줄바꿈으로 나눠 적습니다 (예: Notch, sonic hedgehog). 문단 번역에서 이 용어는 그대로 둡니다. TP53·IL-6 같은 유전자·단백질 이름, Escherichia coli·E. coli 같은 종 이름, 5 µM·10 mg/mL 같은 단위는 적지 않아도 그대로 둡니다. DeepL과 Translate for Zotero에 적용되며, AI 번역은 지시문으로 같은 규칙을 따릅니다.": "用逗号或换行分隔需保持原样的术语，例如 Notch、sonic hedgehog。段落翻译不会改写这些术语。TP53、IL-6 等基因或蛋白名称，Escherichia coli、E. coli 等物种名称，以及 5 µM、10 mg/mL 等数值和单位会自动保护，无需重复填写。此规则用于 DeepL 和 Translate for Zotero；AI 翻译则通过提示词遵守同样要求。",
