 "이 문헌에는 게재본 기록이 없습니다. 자료 점검에서 철회·게재 신호를 먼저 채우세요.": "此条目没有正式版记录。请先在数据检查中补齐撤稿与发表状态信息。",
 "이 문헌에는 아직 노트가 없습니다. 위에 첫 노트를 쓰세요.": "本文暂无笔记，可在上方撰写第一条。",
