 "이 범위에는 최근 활동 시각이 기록된 문헌이 없습니다. 문헌을 열어 읽거나 추가·수정하면 여기에 표시됩니다.": "当前范围尚无活动时间记录。文献打开、添加或编辑后会在此显示。",
 "이 범위에서 연결이 없는 논문": "当前范围内暂无关联",
