 "이 범위의 문헌 {0}편을 인용한 최근 {1}일 논문을 OpenAlex에서 찾습니다. 내 문헌을 많이 인용한 순서로 보여 줍니다.": "从 OpenAlex 查找近 {1} 天内引用此处 {0} 篇文献的新论文，优先显示引用库内文献数量较多的论文。",
 "이 범위의 문헌을 인용한 새 논문입니다. 내 문헌을 많이 인용한 순서입니다.": "引用当前范围内文献的新论文，优先显示引用库内文献数量较多的论文。",
