 "이 수를 넘는 주석은 「더 보기」를 누를 때 이어서 그립니다. 주석이 수백 개인 서재에서 탭이 빨리 열립니다.": "超过首批显示数量的内容，会在点击“显示更多”后加载，以减少大量批注时的初次打开等待。",
