 "켜면 논문을 열 때(논문마다 한 번) 제목·초록·본문 일부를 AI로 보내 요약을 만듭니다. 주소를 비워 두면 이 Mac의 AI 브리지(Claude·ChatGPT 계정의 사용 한도를 씀)로, 주소를 넣으면 그 서버로 보냅니다. 서버가 요금을 받는 서비스라면 열 때마다 비용이 듭니다. 그래서 기본은 꺼짐이고, 꺼져 있으면 리더 패널의 ‘요약 만들기’ 버튼을 눌러야만 보냅니다. 이 Mac에서 실행하는 로컬 모델(Ollama 등, http://localhost:11434/v1/chat/completions)을 연결하면 요청이 이 Mac 밖으로 나가지 않습니다. 한 번 만든 요약은 저장해 두고 다시 보내지 않습니다.": "开启后，首次打开一篇论文时，会发送题名、摘要和部分正文以生成 AI 摘要。未填写服务地址时尝试使用已配置的本地 AI 桥接服务，计入 Claude 或 ChatGPT 账户额度；填写后则发送到指定服务。若服务收费，这些请求会产生费用，因此默认关闭。关闭时需手动点击阅读面板中的“生成摘要”才会请求。使用本机运行的模型，例如地址为 http://localhost:11434/v1/chat/completions 的 Ollama 时，请求不离开本机。已生成的摘要会缓存，不会因再次打开同一论文而重复生成。",
